from rich.console import Console
from rich.panel import Panel

console = Console()
panel = Panel("Content", title="Title", subtitle="Subtitle", style="on blue", border_style="bold white")
segments = list(console.render(panel))

subtitle_found = False
for seg in segments:
    if "Subtitle" in seg.text:
        if "on blue" in str(seg.style):
            subtitle_found = True
            break

if subtitle_found:
    print("SUCCESS: Subtitle has background style")
else:
    print("FAILURE: Subtitle missing background style")
    exit(1)
